// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Ensure deposit is valid ( > MinDeposit = 1 ether initially)
        vm.assume(depositAmount > 1 ether && depositAmount <= type(uint256).max - address(this).balance);
        // Fund this contract to deposit
        vm.deal(address(this), depositAmount);
        // Deposit into C
        (bool depositOk,) = address(c).call{value: depositAmount}("");
        require(depositOk, "deposit failed");
        // Now call CashOut with any withdraw amount (may revert if insufficient balance)
        // We first ensure balance is enough via the deposit
        vm.assume(withdrawAmount <= c.balances(address(this)));
        // Call CashOut
        (bool cashOutOk,) = address(c).call(abi.encodeWithSelector(c.CashOut.selector, withdrawAmount));
        // The rule: regardless of success or failure, MinDeposit should remain initial value
        assertTrue(c.MinDeposit() == 1 ether, "MinDeposit changed");
    }
}

